// Build catalog from Data Tables (single source of truth - NO hardcoding)
const toBool = (v, d) => (v === undefined || v === null || v === '') ? d : String(v).toUpperCase() === 'TRUE';
const catRows = $('Get Catalog Rows').all().map(i => i.json);
const fieldRows = $('Get Field Rows').all().map(i => i.json);
const docRows = $('Get Doc Rows').all().map(i => i.json);

const catalog = {};
for (const r of catRows) {
  const gov = Number(r.government_fee) || 0;
  const sc = Number(r.service_charge) || 0;
  const pct = (r.gst_percent === null || r.gst_percent === undefined || r.gst_percent === '') ? 18 : Number(r.gst_percent);
  const gst = pct === 0 ? 0 : Math.round(sc * pct / 100);
  let steps = [];
  try { steps = JSON.parse(r.processing_steps || '[]'); } catch (e) {}
  catalog[r.service_id] = {
    service_id: r.service_id,
    service_name: r.service_name,
    category: r.category,
    description: r.description,
    government_fee: gov,
    service_charge: sc,
    gst: gst,
    total_fee: gov + sc + gst,
    portal_url: r.portal_url || 'STATE_PORTAL',
    portal_type: r.portal_type || 'PORTAL_OPERATOR',
    operator_required: toBool(r.operator_required, true),
    otp_required: toBool(r.otp_required, false),
    captcha_required: toBool(r.captcha_required, false),
    status_tracking: true,
    receipt_required: toBool(r.receipt_required, true),
    processing_steps: steps,
    active: true,
    required_fields: fieldRows.filter(f => f.service_id === r.service_id).sort((a, b) => (Number(a.field_order) || 0) - (Number(b.field_order) || 0)).map(f => f.field_key),
    required_documents: docRows.filter(d => d.service_id === r.service_id).sort((a, b) => (Number(a.doc_order) || 0) - (Number(b.doc_order) || 0)).map(d => d.doc_key)
  };
}
return [{ json: { catalog } }];

// Select & validate service from catalog
const { catalog } = $('Build Catalog').first().json;
const serviceId = ($('Trigger').first().json.service_id || '').toString().toUpperCase().trim();
const active = Object.values(catalog).filter(s => s.active);

if (!serviceId) {
  return [{ json: { ok: true, catalog: active } }];
}
const svc = catalog[serviceId];
if (!svc || !svc.active) {
  return [{ json: { ok: false, error: 'SERVICE_NOT_FOUND', message: 'Main aapki request ko clearly samajh nahi paaya. Kripya niche diye gaye services mein se select karein.', available: active.map(s => s.service_id) } }];
}
return [{ json: { ok: true, service: svc } }];

const t = $('Trigger').first().json;
const exists = $json.phone ? true : false;
const customer = exists ? $json : { phone: t.phone, full_name: t.name || 'Customer' };
const isNew = !exists;
const msg = isNew ? `Aapka profile ban gaya hai! 🙏` : `Welcome back, ${customer.full_name}! 🙏`;
return [{ json: { customer, is_new: isNew, profile_msg: msg } }];

// Build classification prompt with live catalog (spec section 2)
const catalog = $json.catalog || [];
const t = $('Trigger').first().json;
const message = (t.message || '').toString().slice(0, 500);
const list = catalog.map(s => s.service_id + ' | ' + s.service_name).join('\n');

const prompt = 'You are the intent classifier of CSC Smart Seva, an Indian government services (CSC) WhatsApp assistant.\n'
+ 'Customer message: "' + message + '"\n\n'
+ 'Available services:\n' + list + '\n\n'
+ 'Classify the request. Respond ONLY with strict JSON (no markdown, no explanation, no thinking):\n'
+ '{"service":"<SERVICE_ID or UNKNOWN>","intent":"NEW_APPLICATION|STATUS_CHECK|HUMAN_AGENT|GREETING|GENERAL_QUESTION","confidence":0.0}\n\n'
+ 'Rules:\n'
+ '- NEVER invent a service. If not in the list above, use UNKNOWN.\n'
+ '- Keywords human/agent/operator/help -> intent HUMAN_AGENT.\n'
+ '- Keywords status/track -> intent STATUS_CHECK.\n'
+ '- Greeting only (hi/hello/namaste) -> intent GREETING, service UNKNOWN.\n'
+ '- Confidence below 0.6 -> service UNKNOWN.\n'
+ '- Examples: "pan card banana hai" -> PAN_CARD; "itr bharni hai" -> ITR_FILING; "gst registration" -> GST_REG; "mool niwas banwana hai" -> DOMICILE; "job ka form bharna hai" -> GOV_JOB_FORM; "ration card banana hai" -> RATION_CARD; "passport banwana hai" -> PASSPORT.';

return [{ json: { prompt, phone: t.phone, name: t.name } }];

// Validate AI output + build Hinglish reply (spec sections 1, 2, 24)
const raw = ($json.text || '').replace(/\`\`\`json|\`\`\`/g, '').trim();
let ai;
try { ai = JSON.parse(raw); } catch (e) { ai = { service: 'UNKNOWN', intent: 'GREETING', confidence: 0 }; }

const { catalog } = $('Get Service Catalog').first().json;
const t = $('Trigger').first().json;
const phone = t.phone || '';
const name = t.name || 'Customer';

const svcList = catalog.map((s, i) => (i + 1) + '. ' + s.service_name).join('\n');
const greeting = '\ud83d\ude4f Namaste ' + name + '!\n\nCSC Smart Seva mein aapka swagat hai.\nAap kis service ke liye sahayata chahte hain?\n\n' + svcList + '\n\nYa apna kaam seedha type karein.';

let reply, service_id = ai.service || 'UNKNOWN', intent = ai.intent || 'GREETING', confidence = Number(ai.confidence) || 0;

if (intent === 'HUMAN_AGENT') {
  reply = '\ud83d\udc64\u200d\ud83d\udcbc Aapki chat CSC operator ko transfer ki ja rahi hai.\nKripya thodi der pratiyeksha karein.';
} else if (intent === 'STATUS_CHECK') {
  reply = '\ud83d\udccb Aapki applications jald hi yahan dikhengi.\n(Status tracking engine Phase 9 mein enable hoga.)\n\nAbhi ke liye service select karein ya operator se baat karein - HUMAN likhein.';
} else if (service_id !== 'UNKNOWN' && catalog.find(s => s.service_id === service_id) && confidence >= 0.6) {
  const svc = catalog.find(s => s.service_id === service_id);
  reply = '\u2705 Samajh gaya! Aapko \"' + svc.service_name + '\" chahiye.\n\n\ud83d\udcb5 Approx fee: Rs ' + svc.total_fee + ' (Govt: ' + svc.government_fee + ' + Service: ' + svc.service_charge + ' + GST: ' + svc.gst + ')\n\nAgar sahi hai to CONFIRM likhein, ya service badalni ho to dobara type karein.';
} else if (confidence >= 0.6 && intent === 'GENERAL_QUESTION') {
  reply = 'Aapka sawal note kar liya hai. Iski verified jaankari ke liye main aapki request CSC operator ko forward kar raha hoon.\ud83d\udc64\u200d\ud83d\udcbc\n\nFilhaal available services:\n' + svcList;
} else {
  reply = greeting;
}

return [{ json: { reply, phone, name, service_id, intent, confidence } }];

const body = $json.body || $json;
let phone = '', name = '', text = '', msgType = 'unknown';
let media = null;
try {
  const entry = body.entry && body.entry[0];
  const change = entry && entry.changes && entry.changes[0];
  const value = change && change.value;
  const msg = value && value.messages && value.messages[0];
  if (msg) {
    phone = msg.from || '';
    msgType = msg.type || 'text';
    const contact = value.contacts && value.contacts[0];
    name = (contact && contact.profile && contact.profile.name) || 'Customer';
    if (msgType === 'text') text = msg.text && msg.text.body || '';
    else if (msgType === 'image') { media = { id: msg.image && msg.image.id, mime: msg.image && msg.image.mime_type, filename: '' }; }
    else if (msgType === 'document') { media = { id: msg.document && msg.document.id, mime: msg.document && msg.document.mime_type, filename: msg.document && msg.document.filename }; }
    else if (msgType === 'audio' || msgType === 'video' || msgType === 'sticker') { media = { id: (msg[msgType] || {}).id, mime: (msg[msgType] || {}).mime_type, filename: '' }; }
    else if (msgType === 'button') { text = (msg.button || {}).text || ''; }
    else if (msgType === 'interactive') {
      const it = msg.interactive || {};
      text = (it.button_reply && it.button_reply.title) || (it.list_reply && it.list_reply.title) || '';
    }
  }
} catch (e) {}
return [{ json: { phone: phone || 'unknown', name: name || 'Customer', message: text, media, msg_type: media ? 'media' : 'text', is_media: !!media, wa_id: $json.body ? 'meta' : 'test' } }];

const n = $('Normalize Message').first().json;
const state = $('Get Conv State').first().json || {};
const adminRow = $('Get Admin No').first().json || {};
const admin = adminRow.config_value || '';
const phone = n.phone;
const isAdmin = admin !== 'SET_ADMIN_NUMBER' && admin && phone === admin;
let ctx = {};
try { ctx = JSON.parse(state.context_data || '{}'); } catch (e) {}
const handoff = (state.handoff_active || 'FALSE') === 'TRUE';
const st = state.state || '';
const up = String(n.message || '').toUpperCase();

let route = 'ai';
const wantsStatus = /STATUS|CSC-\\d{4}/.test(up);
const wantsHuman = /HUMAN|AGENT|OPERATOR/.test(up);
if (isAdmin) route = 'operator_cmd';
else if (handoff) route = 'handoff_fwd';
else if (wantsHuman) route = 'human_takeover';
else if (wantsStatus) route = 'ai';
else if (n.is_media) route = 'media';
else if (st === 'FIELDS') route = 'fields';
else if (st === 'DOCS') route = 'docs_text';
else if (st === 'PAYMENT') route = 'payment_wait';
else if (st === 'NEW' && ctx.pending_service && /^(CONFIRM|CONFIRM KARO|HAAN|HAANJI|YES|OK|OKAY|THEEK|THIK|SAHI|PAKKA|1)\b/.test(up)) route = 'start_service';
return [{ json: { route, phone, name: n.name, message: n.message, media: n.media, state: st, pending_service: ctx.pending_service || '' } }];

const pid = $('Get Phone ID').first().json.config_value || '';
const token = $('Get WA Token').first().json.config_value || '';
let base = 'https://graph.facebook.com';
try { base = $('Get API Base').first().json.config_value || base; } catch (e) {}
if (!/^https?:\/\//.test(base)) base = 'https://graph.facebook.com';
const ready = pid && token && !pid.startsWith('SET_') && !token.startsWith('SET_');
return [{ json: { ready, pid, token, api_base: base, to: $json.phone, reply: String($json.reply || '').slice(0, 4096) } }];

const action = $json.action || 'get_full_config';
const service_id = $json.service_id || '';
return [{ json: { action, service_id, input: $json } }];

const action = $('Route Action').first().json.action;
const input = $('Route Action').first().json.input;
let service = {};
try { service = $('Get Service Row').first().json || {}; } catch (e) {}
let fields = [], docs = [];
try { fields = $('Get Fields').all().map(i => i.json); } catch (e) {}
try { docs = $('Get Docs').all().map(i => i.json); } catch (e) {}
let pricing = {};
try { pricing = $('Get Pricing Row').first().json || {}; } catch (e) {}
const seenF = new Set(); fields = fields.filter(f => f && f.field_key && !seenF.has(f.field_key) && seenF.add(f.field_key));
fields.sort((a, b) => (a.field_order || 0) - (b.field_order || 0));
const seenD = new Set(); docs = docs.filter(d => d && d.doc_key && !seenD.has(d.doc_key) && seenD.add(d.doc_key));
docs.sort((a, b) => (a.doc_order || 0) - (b.doc_order || 0));
let processing_steps = [];
try { processing_steps = JSON.parse(service.processing_steps || '[]'); } catch (e) {}
const payload = { ok: !!service.service_id, action, service, fields, documents: docs, pricing, processing_steps };
if (action === 'get_pricing') return [{ json: { ok: !!pricing.service_id, action, pricing: { gov_fee: pricing.gov_fee || 0, service_charge: pricing.service_charge || 0, gst_percent: pricing.gst_percent || 0, gst_amount: pricing.gst_amount || 0, total_fee: pricing.total_fee || 0 }, input } }];
return [{ json: payload }];

const rows = $input.all().map(i => i.json).filter(r => r && r.service_id);
const list = rows.map(s => ({ service_id: s.service_id, service_name: s.service_name, category: s.category, description: s.description, total_fee: s.total_fee, gov_fee: s.government_fee, service_charge: s.service_charge }));
return [{ json: { ok: true, action: 'list_services', services: list, catalog: list } }];

const state = $('Get Conv State').first().json || {};
const cfg = $json || {};
const input = $('Trigger').first().json;
const msg = String(input.message || '').trim();
const up = msg.toUpperCase();
const phone = input.phone;

const FIELDS = cfg.fields || [];
const DOCS = cfg.documents || [];
const service = cfg.service || {};
let ctx = {};
try { ctx = JSON.parse(state.context_data || '{}'); } catch (e) {}

if (up === 'CANCEL') return [{ json: { next: 'cancel', phone } }];

const activeState = state.state || '';
const validStates = ['FIELDS', 'DOCS', 'PAYMENT'];
if (!validStates.includes(activeState)) {
  if (!service.service_id) return [{ json: { next: 'no_config', phone } }];
  const application_id = 'APP' + Date.now().toString(36).toUpperCase() + Math.random().toString(36).slice(2, 6).toUpperCase();
  return [{ json: { next: 'start', phone, application_id, service_id: service.service_id, fields: FIELDS, docs: DOCS, service } }];
}

if (activeState === 'PAYMENT') {
  return [{ json: { next: 'payment_note', phone, application_id: ctx.application_id, service } }];
}

if (activeState === 'DOCS') {
  return [{ json: { next: 'ask_doc_reminder', phone, application_id: ctx.application_id, docs: DOCS, ctx, service } }];
}

// FIELDS state
const idx = Number(ctx.field_index || 0);
const field = FIELDS[idx];
if (!field) {
  const application_id = ctx.application_id || ('APP' + Date.now().toString(36).toUpperCase());
  return [{ json: { next: 'all_fields_done', phone, application_id, fields: FIELDS, docs: DOCS, ctx, service } }];
}
return [{ json: { next: 'answer', phone, application_id: ctx.application_id, field, value: msg, fields: FIELDS, docs: DOCS, ctx, service, idx } }];

const cs = $('Compute Step').first().json;
const fields = cs.fields || [];
const first = fields[0];
if (!first) return [{ json: { reply: 'Is service ke liye koi field configured nahi hai. Operator se baat karein - HUMAN likhein.', phone: cs.phone } }];
const svc = cs.service || {};
let msg = '\u2705 Aapne "' + (svc.service_name || cs.service_id) + '" select kiya hai.\n';
msg += 'Ab main aapse zaroori sawal puchunga. Har jawab ke baad next sawal aayega.\nKabhi bhi CANCEL likhkar band kar sakte hain.\n\n';
msg += '\ud83d\udcdd Sawal 1/' + fields.length + ': ' + (first.question || first.label);
if ((first.options || '').trim()) msg += ' (' + first.options.split(',').join(' / ') + ')';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
const nextIdx = Number(cs.idx || 0) + 1;
const fields = cs.fields || [];
return [{ json: { done: nextIdx >= fields.length, nextIdx, fields } }];

const cs = $('Compute Step').first().json;
const next = $('Next Or Done').first().json;
const f = (cs.fields || [])[next.nextIdx] || {};
let msg = '\ud83d\udcdd Sawal ' + (next.nextIdx + 1) + '/' + (cs.fields || []).length + ': ' + (f.question || f.label);
if ((f.options || '').trim()) msg += ' (' + f.options.split(',').join(' / ') + ')';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
const v = $('Validate Answer').first().json;
const f = (cs.fields || [])[Number(cs.idx || 0)] || {};
let msg = '\u26a0\ufe0f ' + (v.error || 'Value sahi nahi hai.') + '\n\n\ud83d\udcdd Dobara likhein: ' + (f.question || f.label);
if ((f.options || '').trim()) msg += ' (' + f.options.split(',').join(' / ') + ')';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
const docs = cs.docs || [];
const svc = cs.service || {};
let msg = '\u2705 Sari details mil gayi hain \ud83d\udcd1\n\n';
msg += 'Ab documents chahiye (' + docs.length + ' items) - "' + (svc.service_name || '') + '" ke liye:\n';
docs.forEach((d, i) => { msg += '\n' + (i + 1) + '. \ud83d\udcc4 ' + (d.label || d.doc_key) + ' - ' + (d.question || 'photo bhejein'); });
msg += '\n\nEk-ek karke photo/PDF bhejein. Sab mil jane ke baad payment link milega.\nCANCEL likhein to band ho jayega.';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
let msg = '\ud83d\udcb3 Aapka payment pending hai.\n';
msg += 'Payment link bheja ja chuka hai. Payment confirm hote hi application aage badhega.\n';
msg += 'Status ke liye STATUS likhein. Sahayata ke liye HUMAN likhein.';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
const docs = cs.docs || [];
let msg = '\ud83d\udcc4 Aapko abhi documents bhejne hain (' + docs.length + ' items).\n';
docs.forEach((d, i) => { msg += '\n' + (i + 1) + '. ' + (d.label || d.doc_key); });
msg += '\n\nPhoto/PDF bhejein, ya CANCEL likhein.';
return [{ json: { reply: msg, phone: cs.phone } }];

const cs = $('Compute Step').first().json;
const f = cs.field || {};
return [{ json: { field_key: f.field_key, field_label: f.label, field_type: f.field_type, options: f.options, error_hint: f.error_hint, value: cs.value } }];

const inp = $json;
const type = (inp.field_type || 'TEXT').toUpperCase();
const raw = (inp.value === undefined || inp.value === null) ? '' : String(inp.value).trim();
const value = raw;
const label = inp.field_label || inp.field_key || 'Field';
const hint = inp.error_hint || '';
const up = value.toUpperCase();
const allowSkip = inp.allow_skip !== false;
function ok(normalized) { return [{ json: { valid: true, normalized, field_key: inp.field_key, field_type: type } }]; }
function bad(msg) { return [{ json: { valid: false, error: msg || hint || (label + ' sahi nahi hai. Dobara try karein.'), field_key: inp.field_key, field_type: type } }]; }
if (up === 'CANCEL') return [{ json: { valid: true, normalized: 'CANCEL', field_key: inp.field_key, field_type: 'CONTROL' } }];
if (up === 'SKIP' && allowSkip) return ok('SKIP');
switch (type) {
  case 'MOBILE': {
    const digits = value.replace(/\D/g, '');
    if (/^[6-9]\d{9}$/.test(digits)) return ok(digits);
    return bad('10 digit ka valid mobile number likhein (6-9 se shuru).');
  }
  case 'EMAIL': {
    if (/^[\w.+-]+@[\w-]+\.[\w.]{2,}$/.test(value)) return ok(value.toLowerCase());
    return bad('Email format galat hai. Jaise: name@gmail.com');
  }
  case 'PAN': {
    if (/^[A-Z]{5}[0-9]{4}[A-Z]$/.test(up)) return ok(up);
    return bad('PAN 10 character ka hota hai, jaise ABCPD1234F.');
  }
  case 'GSTIN': {
    if (/^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z][1-9A-Z]Z[0-9A-Z]$/.test(up)) return ok(up);
    return bad('GSTIN 15 character ka hota hai. Agar nahi hai to SKIP likhein.');
  }
  case 'AADHAAR': {
    const digits = value.replace(/[\s-]/g, '').replace(/\D/g, '');
    if (/^[0-9]{12}$/.test(digits) && !/^(.)\1{11}$/.test(digits)) return ok(digits);
    return bad('12 digit ka Aadhaar number likhein (sirf digits).');
  }
  case 'PINCODE': {
    if (/^[1-9][0-9]{5}$/.test(value)) return ok(value);
    return bad('6 digit ka valid PIN code likhein.');
  }
  case 'DOB': {
    const m = value.match(/^(\d{1,2})[-\/](\d{1,2})[-\/](\d{4})$/);
    if (m) {
      const dd = m[1].padStart(2, '0'), mm = m[2].padStart(2, '0'), yyyy = m[3];
      const dt2 = new Date(yyyy + '-' + mm + '-' + dd);
      if (dt2 && dt2.getDate() === Number(dd) && dt2.getMonth() === Number(mm) - 1 && dt2.getFullYear() >= 1900) return ok(dd + '/' + mm + '/' + yyyy);
    }
    return bad('Date aise likhein: DD/MM/YYYY (jaise 15/08/1998).');
  }
  case 'EPIC': {
    if (/^[A-Z]{3}[0-9]{7}$/.test(up)) return ok(up);
    return bad('Voter ID aise hota hai: ABC1234567 (3 letters + 7 digits).');
  }
  case 'ACCOUNT': {
    const d = value.replace(/[\s-]/g, '');
    if (/^[0-9]{9,18}$/.test(d)) return ok(d);
    return bad('Bank account number 9 se 18 digit ka hota hai.');
  }
  case 'IFSC': {
    if (/^[A-Z]{4}0[A-Z0-9]{6}$/.test(up)) return ok(up);
    return bad('IFSC aise hota hai: SBIN0001234.');
  }
  case 'NUMBER': {
    const n = value.replace(/[,.\s]/g, '');
    if (/^\d+(\.\d+)?$/.test(n)) return ok(String(Number(n)));
    return bad('Sirf number likhein (jaise 180000).');
  }
  case 'CHOICE': {
    const options = (inp.options || '').split(',').map(s => s.trim()).filter(Boolean);
    if (!options.length) return ok(up);
    const found = options.find(o => o.toUpperCase() === up);
    if (found) return ok(found);
    const yes = ['HAAN','HAANJI','YES','Y','OK','HAA','JI','SAHI','THEEK','THIK','1'];
    const no = ['NAHI','NO','N','NA','NAHE','2'];
    if (options.includes('HAAN') && options.includes('NAHI')) {
      if (yes.includes(up)) return ok('HAAN');
      if (no.includes(up)) return ok('NAHI');
    }
    return bad('Inme se ek likhein: ' + options.join(' / '));
  }
  case 'TEXT':
  default: {
    if (value.length >= 2 && value.length <= 500) return ok(value);
    return bad(label + ' thoda detail mein likhein (2-500 characters).');
  }
}

const input = $('Trigger').first().json;
const state = $('Get Conv State').first().json || {};
let ctx = {};
try { ctx = JSON.parse(state.context_data || '{}'); } catch (e) {}
const phone = input.phone;
const media = input.media || null;
const text = String(input.message || '').trim();
if ((state.state || '') !== 'DOCS') {
  return [{ json: { next: 'not_docs', phone, text } }];
}
return [{ json: { next: 'in_docs', phone, media, text, application_id: ctx.application_id, service_id: state.service_id } }];

const cfg = $('Load Config').first().json || {};
const cs = $('Compute').first().json;
const required = cfg.documents || [];
let saved = [];
try { saved = $('Get Saved Docs').all().map(i => i.json).filter(d => d && d.doc_key); } catch (e) {}
const savedKeys = saved.map(d => d.doc_key);
const missing = required.filter(d => !savedKeys.includes(d.doc_key));
const allDone = missing.length === 0;
const hasMedia = !!(cs.media && cs.media.id);
return [{ json: { allDone, hasMedia, missing, nextDoc: missing[0] || null, savedCount: saved.length, phone: cs.phone, application_id: cs.application_id, media: cs.media, text: cs.text, service: cfg.service || {} } }];

const m = $json;
const d = m.nextDoc;
let msg;
if (d) {
  msg = '\ud83d\udcc4 Agla document: "' + (d.label || d.doc_key) + '"\n' + (d.question || 'Photo/PDF bhejein.') + '\n\n(' + m.savedCount + '/' + (m.savedCount + m.missing.length) + ' documents mil gaye)';
} else {
  msg = 'Documents receive ho gaye, processing mein hai...';
}
return [{ json: { reply: msg, phone: m.phone } }];

